cd 'D:\repository\门户\zhi2-web-admin'
$js = @'
const { chromium } = require('@playwright/test');
(async () => {
  const b = await chromium.launch();
  const pg = await b.newPage({ viewport: { width: 1600, height: 900 } });
  const url = process.argv[2] || 'http://127.0.0.1:8081/';
  await pg.goto(url, { waitUntil: 'networkidle', timeout: 60000 }).catch(e=>console.error('goto',e.message));
  await pg.waitForTimeout(2500);
  // find panel containing 付款方式结构
  const el = pg.locator('text=付款方式结构').first();
  const cnt = await el.count();
  console.log('panel found:', cnt);
  if (cnt) {
    const card = el.locator('xpath=ancestor::div[contains(@class,"bg-slate-50")][1]');
    const box = await card.boundingBox().catch(()=>null);
    console.log('card box:', JSON.stringify(box));
    if (box) await pg.screenshot({ path: process.argv[3], clip: {x:Math.max(0,box.x-4),y:Math.max(0,box.y-4),width:box.width+8,height:box.height+8} });
    else await pg.screenshot({ path: process.argv[3] });
  } else {
    await pg.screenshot({ path: process.argv[3], fullPage: false });
  }
  await b.close();
})();
